 if(step===1){decisionDraft={result:'Approve',reason:'',owner:preferredOwner('logistics',t),due:local(future(24))};modal('Review '+r.kind.toLowerCase()+' approval',steps+summary,btn('Continue to decision','approval-next',id,'primary'));}
