function lineSummary(r){const display=(title,lines)=>`<h3 class="spaced">${title}</h3>${table(['Product','SKU','Quantity'],(lines||[]).map(i=>`<tr><td>${esc(i.name)}</td><td>${esc(i.sku||'Unmapped legacy item')}</td><td>${i.expected}</td></tr>`))}`;return (noReturn(r)?`<div class="callout ${waiverApproved(r)?'good':'warn'} spaced"><strong>${waiverApproved(r)?'No-return exception approved':'No-return exception requested'}</strong><br>No items expected back for this request. Other return obligations stay open.<br>Reason: ${esc(r.exceptionReason)}${waiverApproved(r)?'<br>Approved by '+esc(r.waiver.actor)+' · '+fmt(r.waiver.at)+' · '+r.id+' revision '+r.revision:''}</div>`:display(r.kind==='Cancellation'?'Items to cancel':'Items expected back',r.itemLines))+(r.kind==='Replacement'?display('Replacement items to send',r.replacementLines):'');}
function answerRequest(id){const r=db.requests.find(x=>x.id===id),t=ticket(r.ticketId);if(!can('work'))return denied('Provide information');formModal('Provide information · Revision '+r.revision,area('Answer and evidence','answer','','required')+`<div><label for="review-owner">Return to decision owner</label><select id="review-owner" name="ownerId">${ownerOptions(approvers(t),r.approverId)}</select></div>`+field('Decision due (IST)','dueAt',local(future(24)),'datetime-local','required'),'Resubmit same revision',v=>{if(r.final||r.supersededBy||r.status!=='Need information')throw Error('This request no longer awaits information.');validateDue(v.dueAt);if(!approvers(t).some(u=>u.id===v.ownerId))throw Error('Select an eligible approver.');r.reason+=' | CS response: '+v.answer;r.status='Pending decision';r.approverId=v.ownerId;transitionTask('request',r.id,t.id,'decision','Decide '+r.kind.toLowerCase()+' request',v.ownerId,v.dueAt,'Requested information supplied');t.status='Pending review';log(t,'Request information',r.id+': '+v.answer);close();render();toast('Same revision returned for decision; all task views updated.');});}

let taskView='Open',taskSearch='',taskOwnerFilter='All',taskSourceFilter='All',taskListPage=1,reportOwner='All',reportSource='All';
const isOverdue=t=>t.status==='open'&&new Date(t.dueAt)<new Date(now());
const userHas=(u,g)=>u?.roles.some(id=>db.roles.find(r=>r.id===id)?.grants.includes(g));
function eligibleUsers(grant,t){return db.users.filter(u=>eligibleUser(db,u,grant,t));}
function approvers(t){return db.users.filter(u=>u.status==='Active'&&userHas(u,'read')&&managerMayDecide(u,t));}
function ownerOptions(users,selected){return users.map(u=>`<option value="${u.id}" ${u.id===selected?'selected':''}>${esc(u.name)} · ${esc(roleNames(u))}</option>`).join('');}
function csOwner(r){const t=ticket(r.ticketId),users=eligibleUsers('work',t);return users.find(u=>u.id===r.requesterId)?.id||users.find(u=>u.name===t.owner)?.id||users[0]?.id||'';}
function validateDue(value){const at=stamp(value);if(!Number.isFinite(new Date(at).getTime())||new Date(at)<=new Date(now()))throw Error('Choose a future deadline in IST.');return at;}
function transitionTask(sourceType,sourceId,ticketId,step,title,ownerId,dueAt,reason){
 const current=flow.open().find(t=>t.sourceType===sourceType&&t.sourceId===sourceId&&t.step===step);
 if(current){if(current.ownerId!==ownerId||new Date(current.dueAt).getTime()!==new Date(stamp(dueAt)).getTime())flow.revise(current,{ownerId,dueAt,reason});current.title=title;flow.sync();return current;}
 flow.finishSource(sourceType,sourceId,reason);return flow.create({ticketId,sourceType,sourceId,step,title,ownerId,dueAt});
}
function decisionBadges(id){return currentRequests(db,id).map(r=>`<span class="decision-line">${badge(r.kind+': '+r.status)}${r.status==='Rejected'?`<span class="sub">${esc(r.decisionReason||r.reason)}</span>`:''}</span>`).join('');}
function taskCompact(tasks){return tasks.map(t=>`<div class="queue-item"><strong>${esc(t.title)}</strong><p>${esc(t.ticketId||'Unmatched parcel')} · ${fmt(t.dueAt)}</p>${badge(isOverdue(t)?'Overdue':'Upcoming')} ${btn('Open action','task-open',t.id,'small')}</div>`).join('');}
function taskRows(tasks){return table(['Ticket / task','Next action','Current owner / missed owner','Deadline (IST)','State / action'],tasks.map(t=>`<tr><td>${t.ticketId?btn(t.ticketId,'ticket',t.ticketId,'link'):esc(t.sourceId)}<span class="sub">${t.id} · ${esc(t.sourceType)}</span></td><td>${esc(t.title)}<span class="sub">${esc(t.sourceId)}${t.firstMissedAt?' · Missed: '+fmt(t.firstMissedAt):''}</span></td><td>${esc(flow.owner(t.ownerId))}${t.ownerAtFirstMiss?'<span class="sub">At missed deadline: '+esc(flow.owner(t.ownerAtFirstMiss))+'</span>':''}</td><td>${fmt(t.dueAt)}${isOverdue(t)?`<span class="sub danger">${Math.max(1,Math.floor((new Date(now())-new Date(t.dueAt))/60000))} minutes overdue</span>`:''}</td><td>${badge(t.status==='open'?(isOverdue(t)?'Overdue':'Open'):t.status==='completed'?'Completed':'Cancelled')}<div class="spaced">${btn('View task','task-open',t.id,'small')}</div></td></tr>`));}
function matchingTasks(){flow.check();let rows=taskView==='Missed in period'?reportTasks():db.tasks.filter(t=>taskView==='History'?t.status!=='open':t.status==='open');if(taskView==='Mine')rows=rows.filter(t=>t.ownerId===actor);if(taskView==='Overdue')rows=rows.filter(isOverdue);if(taskView==='Decisions')rows=rows.filter(t=>t.step==='decision');if(taskView==='Rejected')rows=rows.filter(t=>t.step==='rejection');return rows.filter(t=>(taskOwnerFilter==='All'||t.ownerId===taskOwnerFilter)&&(taskSourceFilter==='All'||t.sourceType===taskSourceFilter)&&(!taskSearch||recordMatches(db,{...t,owner:flow.owner(t.ownerId)},taskSearch))).sort((a,b)=>new Date(a.dueAt)-new Date(b.dueAt));}
function tasksPage(){const rows=matchingTasks(),pages=Math.max(1,Math.ceil(rows.length/10));taskListPage=Math.min(taskListPage,pages);shell(head('Follow-ups','One task record connects the ticket, service action, reminders and reporting.',can('export')?btn('Export matching tasks','tasks-export'):'' )+`<div class="toolbar">${tabs(['Open','Mine','Overdue','Decisions','Rejected','History'],taskView,'task-view')}</div><div class="toolbar"><input id="task-search" aria-label="Search follow-ups" placeholder="Search ticket, email, phone, task, action or reference..." value="${esc(taskSearch)}"><select id="task-owner" aria-label="Filter task owner"><option value="All">All responsible people</option>${ownerOptions(db.users,taskOwnerFilter)}</select><select id="task-source" aria-label="Filter task type">${opt(['All','ticket','request','return','waiver','refund','dispute','parcel'],taskSourceFilter)}</select></div>${taskView==='Missed in period'?`<div class="callout">First missed deadline: ${insights.from} to ${insights.to} · ${esc(reportOwner==='All'?'All owners':flow.owner(reportOwner))} · Task dates, independent of ticket creation date.</div>`:''}<section class="card spaced">${taskRows(rows.slice((taskListPage-1)*10,taskListPage*10))}<div class="table-footer"><span>${rows.length} matching tasks · Page ${taskListPage} of ${pages}</span><div class="actions"><button data-act="task-prev" ${taskListPage===1?'disabled':''}>Previous</button><button data-act="task-next" ${taskListPage===pages?'disabled':''}>Next</button></div></div></section><p class="field-hint">Reminders run in this open review tab. Background tabs may show them late. Refresh resets demo changes.</p>`);$('#task-search').oninput=e=>{const caret=e.target.selectionStart;taskSearch=e.target.value;taskListPage=1;render();const input=$('#task-search');input.focus();input.setSelectionRange(caret,caret);};$('#task-owner').onchange=e=>{taskOwnerFilter=e.target.value;taskListPage=1;render();};$('#task-source').onchange=e=>{taskSourceFilter=e.target.value;taskListPage=1;render();};}
function taskExport(rows){flow.check();return rows.map(t=>({task_id:t.id,ticket_id:t.ticketId,source_type:t.sourceType,source_id:t.sourceId,stage:t.step,action:t.title,owner_id:t.ownerId,owner:flow.owner(t.ownerId),original_due:t.originalDueAt,current_due:t.dueAt,first_missed_deadline:t.firstMissedAt,owner_at_first_miss:t.ownerAtFirstMiss?flow.owner(t.ownerAtFirstMiss):'',completed_at:t.completedAt,completion_recorded_at:t.completionRecordedAt||'',cancelled_at:t.cancelledAt||'',status:t.status,reminder_at:t.remindAt,history_coverage:t.coverage,outcome:t.outcome||'',history:t.history}));}
function mayManageTask(t){return t.status==='open'&&(t.ownerId===actor||can('assign')&&(!t.ticketId||inScope(ticket(t.ticketId)))||user().roles.includes('super'));}
function taskDetail(id){const t=flow.get(id);if(!t)return;modal('Follow-up · '+t.id,`${badge(isOverdue(t)?'Overdue':t.status)}<h3 class="spaced">${esc(t.title)}</h3><dl class="fact-list spaced"><dt>Ticket / source</dt><dd>${esc(t.ticketId||'Not yet matched')} · ${esc(t.sourceId)}</dd><dt>Responsible person</dt><dd>${esc(flow.owner(t.ownerId))}</dd><dt>Task due</dt><dd>${fmt(t.dueAt)}</dd><dt>Original deadline</dt><dd>${fmt(t.originalDueAt)}</dd><dt>First missed deadline</dt><dd>${fmt(t.firstMissedAt)}${t.ownerAtFirstMiss?' · '+esc(flow.owner(t.ownerAtFirstMiss)):''}</dd><dt>Reminder time</dt><dd>${fmt(t.remindAt)}</dd><dt>Completed</dt><dd>${fmt(t.completedAt)} · ${esc(t.outcome||'—')}</dd></dl><div class="callout spaced">${t.coverage==='complete'?'Task history is recorded below.':'Migrated sample: earlier task history is unavailable. Excluded from historical missed-follow-up totals.'}</div><div class="timeline spaced">${[...t.history].reverse().map(h=>`<div class="event"><strong>${esc(h.action)}</strong><p>${esc(h.reason||'')}${h.before?'<br>Was: '+esc(flow.owner(h.before.ownerId))+' · '+fmt(h.before.dueAt)+'<br>Now: '+esc(flow.owner(h.after.ownerId))+' · '+fmt(h.after.dueAt):''}</p><span class="meta">${esc(h.actor)} · ${fmt(h.at)}</span></div>`).join('')}</div>`,`${t.status==='open'?btn('Open related action','task-source',id,'primary'):t.ticketId?btn('View ticket','ticket',t.ticketId):''}${t.sourceType==='ticket'&&t.status==='open'&&can('work')?btn('Complete follow-up','task-complete',id):''}${mayManageTask(t)?btn('Change owner / deadline','task-edit',id):''}${t.ownerId===actor&&t.status==='open'?btn('Remind in 15 minutes','task-snooze',id):''}`);}
function editTask(id){
 const task=flow.get(id);if(!task||!mayManageTask(task))return denied('Manage task');
 const users=db.users.filter(u=>taskOwnerEligible(db,u,task));
 formModal('Change follow-up owner / deadline',`<div><label for="task-new-owner">Responsible person</label><select name="ownerId" id="task-new-owner">${ownerOptions(users,task.ownerId)}</select></div>`+field('Task due (IST)','dueAt',local(task.dueAt),'datetime-local','required')+area('Reason for changing this commitment','reason','','required')+`<div class="wide callout">Only active people with the required permissions and country scope are listed. The original deadline and any missed commitment remain in history.</div>`,'Save task change',v=>{
  if(!taskOwnerEligible(db,db.users.find(u=>u.id===v.ownerId),task))throw Error('Select an active, eligible owner for this task and country.');
  if(task.sourceType==='dispute'&&task.step==='evidence'&&Math.floor(new Date(stamp(v.dueAt))/60000)!==Math.floor(new Date(task.dueAt)/60000))throw Error('The provider submission deadline stays fixed. Change the reminder or owner instead.');
  flow.revise(task,v);if(task.ticketId)log(ticket(task.ticketId),'Task changed',task.id+': '+v.reason);close();render();toast('Task updated everywhere; previous deadline retained.');
 });
}
function addFollowup(id){
 if(!can('work'))return denied('Add follow-up');const t=ticket(id);
 try{assertActiveWork(t);}catch(error){return toast(error.message);}
 formModal('Add a customer follow-up',sel('Next action','title',['Contact customer','Check customer response','Share troubleshooting steps','Confirm delivery with customer','Confirm refund update','Review unresolved issue'])+`<div><label for="follow-owner">Responsible person</label><select name="ownerId" id="follow-owner">${ownerOptions(eligibleUsers('work',t),actor)}</select></div>`+field('Due at (IST)','dueAt',local(future(24)),'datetime-local','required'),'Add follow-up',v=>{
  assertActiveWork(t);validateDue(v.dueAt);if(!eligibleUsers('work',t).some(u=>u.id===v.ownerId))throw Error('Select an active CS owner in this country scope.');
  const task=flow.create({...v,ticketId:id,sourceId:'FOLLOWUP-'+(++db.next)});log(t,'Follow-up added',task.id+': '+v.title);close();render();toast('Follow-up added with an automatic reminder.');
 });
}
function managerEscalations(){return user().roles.some(r=>['super','head','cm'].includes(r))?flow.open().filter(t=>isOverdue(t)&&(!t.ticketId||inScope(ticket(t.ticketId)))):[];}
function reminderLabel(){const count=managerEscalations().length;return 'Reminders ('+flow.reminders(actor).length+')'+(count?' · Team overdue ('+count+')':'');}
function reminderPanel(){const tasks=flow.reminders(actor);modal('My reminders · '+tasks.length,`${managerEscalations().length?'<div class="callout warn"><strong>Manager attention · '+managerEscalations().length+' overdue follow-ups</strong><p>Automatically raised for your operational scope. Review or hand over the task; agent snoozing does not hide these items.</p>'+taskCompact(managerEscalations())+'</div>':''}<p>One hour before the task deadline, unless snoozed. Snooze does not change the deadline.</p><div class="callout">Review reminders run in this open tab. Background tabs may show them late. Refresh resets demo changes.</div>`+(tasks.length?tasks.map(t=>`<div class="queue-item"><h3>${esc(t.title)}</h3><p>${esc(t.ticketId||t.sourceId)} · Task due ${fmt(t.dueAt)}</p>${badge(isOverdue(t)?'Overdue':'Due soon')}<div class="actions spaced">${btn('Open task','task-open',t.id)}${btn('Remind in 15 minutes','task-snooze',t.id)}${btn('Choose reminder time','task-snooze-custom',t.id)}</div></div>`).join(''):'<p class="spaced">No reminders are due for you.</p>'));}
let reminderNotified=new Set();
function refreshReminderCount(){flow.check();const tasks=can('read')?flow.reminders(actor):[],b=$('.reminder-button');if(b)b.textContent=reminderLabel();const fresh=[...tasks,...managerEscalations().filter(t=>t.ownerId!==actor)].filter(t=>!reminderNotified.has(actor+':'+t.id+':'+t.remindAt));if(fresh.length&&document.visibilityState==='visible'){fresh.forEach(t=>reminderNotified.add(actor+':'+t.id+':'+t.remindAt));toast(fresh.length+' follow-up alert'+(fresh.length===1?'':'s')+' due. Open Reminders to review.');}}
function preferredOwner(grant,t){const users=eligibleUsers(grant,t);return users.find(u=>u.roles.includes(grant))?.id||users[0]?.id||'';}
function assignTicket(id){if(!can('assign'))return denied('Assign ticket');const t=ticket(id);if(!inScope(t))return denied('Assignment outside your scope');const users=eligibleUsers('work',t);formModal('Assign ticket '+id,`<div><label for="ticket-owner">Ticket owner</label><select id="ticket-owner" name="ownerId">${ownerOptions(users,flow.ownerId(t.owner))}</select></div><div class="wide callout">Each follow-up has its own responsible person. Change those in Follow-ups when a task also needs handover.</div>`,'Save ticket owner',v=>{if(!users.some(u=>u.id===v.ownerId))throw Error('Choose an eligible ticket owner.');t.owner=flow.owner(v.ownerId);log(t,'Assignment','Ticket assigned to '+t.owner);close();render();});}
function openTaskSource(id){const t=flow.get(id);if(!t)return;close();if(t.status!=='open')return t.ticketId?navigate('ticket',t.ticketId):taskDetail(id);if(t.step==='customer-update')return navigate('ticket',t.ticketId);if(t.sourceType==='request'){if(['rejection','remedy'].includes(t.step))return navigate('ticket',t.ticketId);return approval(t.sourceId);}if(t.sourceType==='waiver')return reviewWaiver(t.sourceId);if(t.sourceType==='return')return openReturn(t.sourceId);if(t.sourceType==='refund')return refund(t.sourceId);if(t.sourceType==='dispute')return dispute(t.sourceId);if(t.sourceType==='parcel')return action('unmatched-list');return navigate('ticket',t.ticketId);}
function reportScope(t){const ticketRecord=ticket(t.ticketId);return (insights.brand==='All brands'||ticketRecord?.brand===insights.brand)&&(insights.country==='All countries'||ticketRecord?.country===insights.country)&&(reportOwner==='All'||(t.ownerAtFirstMiss||t.ownerId)===reportOwner)&&(reportSource==='All'||t.sourceType===reportSource);}
function reportTasks(){return flow.missed(insights.from,insights.to).filter(reportScope);}
function followupInsights(){const rows=reportTasks(),days=Math.round((new Date(insights.to)-new Date(insights.from))/86400000)+1,previous=flow.missed(dateShift(insights.from,-days),dateShift(insights.from,-1)).filter(reportScope),overdue=flow.open().filter(t=>isOverdue(t)&&reportScope(t)),unknown=db.tasks.filter(t=>t.coverage!=='complete'&&reportScope(t));return card('Missed follow-ups',`<p>First missed deadline between <strong>${insights.from}</strong> and <strong>${insights.to}</strong>, IST. Each task is counted once, even after it is rescheduled or completed late. Ticket creation date does not limit this report.</p><div class="toolbar spaced"><select id="report-owner" aria-label="Follow-up report responsible person"><option value="All">All responsible people at missed deadline</option>${ownerOptions(db.users,reportOwner)}</select><select id="report-source" aria-label="Follow-up report task type">${opt(['All','ticket','request','return','waiver','refund','dispute','parcel'],reportSource)}</select></div>${stats([['Missed in selected period',rows.length,metricDiff(rows.length,previous.length).replace('comparison','preceding equal period')],['Completed after a miss',rows.filter(t=>t.status==='completed').length,'Historical breaches remain visible'],['Overdue now',overdue.length,'Open tasks at the current time'],['Linked tickets',new Set(rows.map(t=>t.ticketId).filter(Boolean)).size,'Separate from the task count']])}<div class="actions">${btn('View all missed tasks','task-view','Missed in period')}${can('export')?btn('Export missed follow-ups','report-export'):''}</div><div class="spaced">${taskRows(rows.slice(0,5))}</div><p class="field-hint">${rows.length} matching tasks; showing up to 5. ${unknown.length} imported sample tasks lack earlier history and are excluded from historical totals. They remain in current operational queues.</p>`);}
function bindFollowupInsights(){if($('#report-owner'))$('#report-owner').onchange=e=>{reportOwner=e.target.value;render();};if($('#report-source'))$('#report-source').onchange=e=>{reportSource=e.target.value;render();};}
function operationAction(a,arg){switch(a){
 case 'open-team':navigate('tickets','',{openOnly:true});break;
 case 'dashboard-all':navigate('tickets','',{openOnly:true,...(tab==='Tickets assigned to me'?{owner:person()}:{})});break;
 case 'task-view':taskView=arg;taskSearch='';taskOwnerFilter='All';taskSourceFilter='All';taskListPage=1;close();navigate('tasks');break;
 case 'task-prev':taskListPage--;render();break;case 'task-next':taskListPage++;render();break;
 case 'task-complete':completeFollowup(arg);break;case 'task-open':taskDetail(arg);break;case 'task-edit':editTask(arg);break;case 'task-add':addFollowup(arg);break;case 'task-source':openTaskSource(arg);break;
 case 'tasks-export':downloadRows('follow-ups',taskExport(matchingTasks()));break;case 'report-export':downloadRows('missed-follow-ups',taskExport(reportTasks()));break;
 case 'reminders':reminderPanel();break;
 case 'task-snooze':{const t=flow.get(arg);if(t.ownerId!==actor)return denied('Snooze another person’s reminder'),true;flow.snooze(t,15);close();render();toast('Reminder moved by 15 minutes. Task deadline is unchanged.');break;}
 case 'task-snooze-custom':{const t=flow.get(arg);if(t.ownerId!==actor)return true;formModal('Choose reminder time',field('Remind me at (IST)','at',local(future(.5)),'datetime-local','required')+`<div class="wide callout">Task due stays ${fmt(t.dueAt)}. Overdue work remains visible.</div>`,'Snooze reminder',v=>{const at=validateDue(v.at);flow.snooze(t,(new Date(at)-new Date(now()))/60000);close();render();toast('Reminder changed; deadline retained.');});break;}
 case 'copy-value':navigator.clipboard.writeText(arg).then(()=>toast('Copied.')).catch(()=>modal('Copy this value',field('Value','copy-value',arg)));break;
 default:return false;
 }return true;}

function completeFollowup(id){const t=flow.get(id);if(!can('work')||t.sourceType!=='ticket'||t.status!=='open')return denied('Complete follow-up');if(classificationCompletionIssue(t,ticket(t.ticketId)))return modal('Classification is required',`<p>A manager must choose the ticket’s query type, main category and child category before this action can finish.</p>`,btn('Open ticket','ticket',t.ticketId,'primary'));formModal('Complete customer follow-up',sel('Outcome','outcome',['Customer contacted','Customer reply reviewed','Troubleshooting shared','Issue reviewed'])+area('Brief evidence / outcome','note','','required')+`<label class="wide check"><input name="actual" type="checkbox" required>I confirm this action has been completed</label>`,'Record completed action',v=>{const issue=classificationCompletionIssue(t,ticket(t.ticketId));if(issue)throw Error(issue);if(ticket(t.ticketId).worker!==person())throw Error('Open the ticket and Start working before completing a CS action.');flow.finish(t,v.outcome+': '+v.note);log(ticket(t.ticketId),'Follow-up completed',t.id+': '+v.note);close();render();});}

flow.seed();
render();
setInterval(refreshReminderCount,30000);refreshReminderCount();
document.addEventListener('visibilitychange',refreshReminderCount);
if(document.modelContext?.registerTool){
 document.modelContext.registerTool({name:'read_support_tickets',description:'Read synthetic prototype tickets matching a search. Does not change records.',inputSchema:{type:'object',properties:{search:{type:'string'}},additionalProperties:false},execute:async({search=''})=>({tickets:!can('read')?[]:flatTickets(db.tickets.filter(t=>!t.test&&matches(t,search)))})});
 document.modelContext.registerTool({name:'start_ticket_review',description:'Open a synthetic ticket workspace for review. Does not claim work or send messages.',inputSchema:{type:'object',properties:{ticket_id:{type:'string'}},required:['ticket_id'],additionalProperties:false},execute:async({ticket_id})=>{if(!can('read'))return {error:'Shared read permission required'};if(!ticket(ticket_id))return {error:'Ticket not found'};navigate('ticket',ticket_id);return {opened:ticket_id};}});
}
